static UBYTE unlocked(void){if(rf.quest_flags[31]&128)return 1;return 0;}
static UBYTE count(void){UBYTE n=starts[rf_region_district+1]-starts[rf_region_district];if(nodes[starts[rf_region_district]+n-1].hidden&&!unlocked())n--;return n;}
static const TrailNode*selected(void){return nodes+starts[rf_region_district]+rf_region_cursor;}
static UBYTE select_id(UWORD id){UBYTE d,i;for(d=0;d<16;d++)for(i=0;i<starts[d+1]-starts[d];i++){const TrailNode*n=nodes+starts[d]+i;if(n->id==id){if(n->hidden&&!unlocked())return 0;rf_region_district=d;rf_region_cursor=i;return 1;}}return 0;}
static UBYTE ordinal(UWORD id){UWORD i;for(i=starts[rf_region_district];i<starts[rf_region_district+1];i++)if(nodes[i].id==id)return i-starts[rf_region_district]+1;return 0;}
static void two(UBYTE x,UBYTE y,UBYTE n){char b[3];b[0]='0'+n/10;b[1]='0'+n%10;b[2]=0;text(x,y,b);}
void rf_region_open(UWORD map,UBYTE origin) BANKED {rf_region_origin=origin;if(!select_id(map)){rf_region_district=rf_map.district;if(rf_region_district>15)rf_region_district=0;rf_region_cursor=0;}}
void rf_region_move(UBYTE key) BANKED {UBYTE n=count(),step=0;if(key&J_LEFT)step=n-1;else if(key&J_RIGHT)step=1;else if(key&J_UP)step=n-(5%n);else if(key&J_DOWN)step=5%n;rf_region_cursor=(rf_region_cursor+step)%n;}
UBYTE rf_region_follow(UBYTE key) BANKED {const TrailNode*n=selected();UWORD id=65535;if(key&J_LEFT)id=n->west;else if(key&J_RIGHT)id=n->east;else if(key&J_UP)id=n->north;else if(key&J_DOWN)id=n->south;if(id==65535)return 0;return select_id(id);}
UWORD rf_region_selected(void) BANKED{return selected()->id;}
void rf_ui_region_map(void) BANKED {
 UBYTE i,x,y,n=count(),target;char marker[2];const TrailNode*t;clear();line(0,districts[rf_region_district]);line(1,selected()->name);line(2,"FICTIONAL N/S LINKS");
 for(i=0;i<n;i++){t=nodes+starts[rf_region_district]+i;x=(i%5)*4;y=4+(i/5)*3;marker[0]='.';marker[1]=0;
  if(rf.visited_maps[t->id/8]&(1<<(t->id%8)))marker[0]='*';if(t->id==rf.room)marker[0]='@';if(i==rf_region_cursor)marker[0]='>';
  text(x,y,marker);two(x+1,y,i+1);if(t->east!=65535)text(x+3,y,">");
  if(t->north!=65535){target=ordinal(t->north);text(x,y+1,"N");if(target)two(x+1,y+1,target);else text(x+1,y+1,"--");}
  else if(t->south!=65535){target=ordinal(t->south);text(x,y+1,"S");if(target)two(x+1,y+1,target);else text(x+1,y+1,"--");}
  if(t->camp)text(x+3,y+1,"^");
 }
 line(15,"*SEEN ^CAMP @HERE");line(16,"D-PAD:PLAN A:DETAIL");line(17,"B: BACK");
}
static void neighbor(UBYTE y,const char*direction,UWORD id){UWORD i;line(y,direction);if(id==65535){line(y+1,"NO TRAIL HERE");return;}for(i=0;i<241;i++)if(nodes[i].id==id){if(nodes[i].hidden&&!unlocked()){line(y+1,"UNMARKED TRAIL");return;}line(y+1,nodes[i].name);return;}}
void rf_ui_region_detail(void) BANKED {
 const TrailNode*n=selected();clear();line(0,"TRAIL DETAILS");line(2,n->name);if(n->id==rf.room)line(3,"YOU ARE HERE");else if(rf.visited_maps[n->id/8]&(1<<(n->id%8)))line(3,"YOU HAVE WALKED HERE");else line(3,"NOT YET VISITED");
 neighbor(5,"WEST",n->west);neighbor(8,"EAST",n->east);neighbor(11,"NORTH",n->north);neighbor(14,"SOUTH",n->south);
 if(n->camp)line(1,"^ RANGER CAMP");line(16,"D-PAD: FOLLOW LINKS");line(17,"A:SKETCH B:RETURN");
}
